fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants to consider (at most n)
    let limit = n.min(participations.len() as u8) as usize;

    // Count eligible participants:
    // A participant is eligible if (5 - attendance_count) >= k
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&att| 5u8.saturating_sub(att) >= k)
        .count() as u8;

    // Maximum number of teams of 3 disjoint participants
    eligible_count / 3
}